package httpapi

import {
	"encoding/json"
	"errors"
	"net/http"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/go-chi/chi/v5"
	"github.com/prometheus/client_golang/prometheus/promhttp"

	"incident-replay/backend/internal/replay"
	"incident-replay/backend/internal/scenario"
)

const (
	defaultMaxRPS    = 200
	defaultRunsLimit = 20
	scenariosDir     = "./data/scenarios"
	runsDir          = "./data/runs"
)

type Handler struct {
	runner *replay.Runner
}

func NewHandler(runner *replay.Runner) *Handler {
	return &Handler{runner: runner}
}

func (h *Handler) Routes() http.Handler {
	r := chi.NewRouter()
	r.Use(withLogging)
	r.Use(withJSON)

	r.Get("/healthz", h.healthz)
	r.Handle("/metrics", promhttp.Handler())

	r.Post("/replay/start", h.replayStart)
	r.Post("/replay/stop", h.replayStop)
	r.Get("/replay/status", h.replayStatus)
	r.Get("/replay/runs", h.replayRuns)
	r.Get("/replay/report", h.replayReport)

	r.Post("/scenarios/upload", h.scenariosUpload)
	r.Get("/scenarios/list", h.scenariosList)

	return r
}

func (h *Handler) healthz(w http.ResponseWriter, _ *http.Request) {
	if err := ensureWritableDir(scenariosDir); err != nil {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{
			"status": "degraded",
			"error":  err.Error(),
		})
		return
	}
	if err := ensureWritableDir(runsDir); err != nil {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{
			"status": "degraded",
			"error":  err.Error(),
		})
		return
	}

	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

func ensureWritableDir(path string) error {
	if err := os.MkdirAll(path, 0o755); err != nil {
		return err
	}

	// try to create and remove a temp file to verify writability
	f, err := os.CreateTemp(path, ".probe-*")
	if err != nil {
		return err
	}
	name := f.Name()
	_ = f.Close()
	if err := os.Remove(name); err != nil {
		return err
	}
	return nil
}

func (h *Handler) replayStart(w http.ResponseWriter, r *http.Request) {
	if h.runner.IsShuttingDown() {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "shutting_down"})
		return
	}

	var req struct {
		ScenarioID    string  `json:"scenarioId"`
		TargetBaseURL string  `json:"targetBaseUrl"`
		RPS           int     `json:"rps"`
		DurationSec   int     `json:"durationSec"`
		Mode          string  `json:"mode"`
		Speed         float64 `json:"speed"`
		MaxDelayMs    int     `json:"maxDelayMs"`
		StartFromTs   string  `json:"startFromTs"`
		EndAtTs       string  `json:"endAtTs"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid_request"})
		return
	}

	maxRPS := defaultMaxRPS
	if envMaxRPS := os.Getenv("MAX_RPS_PER_RUN"); envMaxRPS != "" {
		if val, err := strconv.Atoi(envMaxRPS); err == nil && val > 0 {
			maxRPS = val
		}
	}
	if req.RPS <= 0 || req.RPS > maxRPS {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid_rps"})
		return
	}

	params := replay.StartParams{
		ScenarioID:    req.ScenarioID,
		TargetBaseURL: req.TargetBaseURL,
		RPS:           req.RPS,
		Duration:      time.Duration(req.DurationSec) * time.Second,
		Mode:          req.Mode,
		Speed:         req.Speed,
		MaxDelayMs:    int64(req.MaxDelayMs),
		StartFromTs:   req.StartFromTs,
		EndAtTs:       req.EndAtTs,
	}

	runID, err := h.runner.Start(params)
	if err != nil {
		msg := err.Error()
		switch {
		case strings.Contains(msg, "too_many_concurrent_runs"):
			writeJSON(w, http.StatusTooManyRequests, map[string]string{"error": "too_many_concurrent_runs"})
		case strings.Contains(msg, "required"), strings.Contains(msg, "must be"), strings.Contains(msg, "invalid"), strings.Contains(msg, "load scenario error"):
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": msg})
		default:
			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal_error"})
		}
		return
	}

	writeJSON(w, http.StatusOK, map[string]string{
		"runId":  runID,
		"status": "started",
	})
}

func (h *Handler) replayStop(w http.ResponseWriter, r *http.Request) {
	var req struct {
		RunID string `json:"runId"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil || strings.TrimSpace(req.RunID) == "" {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid_request"})
		return
	}

	if err := h.runner.Stop(req.RunID); err != nil {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}

	writeJSON(w, http.StatusOK, map[string]string{"runId": req.RunID, "status": "stopped"})
}

func (h *Handler) replayStatus(w http.ResponseWriter, r *http.Request) {
	runID := strings.TrimSpace(r.URL.Query().Get("runId"))
	if runID == "" {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "runId is required"})
		return
	}
	status, err := h.runner.Status(runID)
	if err != nil {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}
	writeJSON(w, http.StatusOK, status)
}

func (h *Handler) replayRuns(w http.ResponseWriter, r *http.Request) {
	limit := defaultRunsLimit
	if raw := strings.TrimSpace(r.URL.Query().Get("limit")); raw != "" {
		if parsed, err := strconv.Atoi(raw); err == nil && parsed > 0 {
			limit = parsed
		}
	}

	runs, err := h.runner.ListRuns(limit)
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal_error"})
		return
	}
	writeJSON(w, http.StatusOK, runs)
}

func (h *Handler) replayReport(w http.ResponseWriter, r *http.Request) {
	runID := strings.TrimSpace(r.URL.Query().Get("runId"))
	if runID == "" {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "runId is required"})
		return
	}

	report, err := h.runner.LoadReport(runID)
	if err != nil {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": "report_not_found"})
		return
	}
	writeJSON(w, http.StatusOK, report)
}

func (h *Handler) scenariosUpload(w http.ResponseWriter, r *http.Request) {
	var req struct {
		ScenarioID string `json:"scenarioId"`
		JSONL      string `json:"jsonl"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid_request"})
		return
	}
	if !scenario.ValidScenarioID(req.ScenarioID) {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid_scenario_id"})
		return
	}
	if strings.TrimSpace(req.JSONL) == "" {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "jsonl is required"})
		return
	}

	if err := os.MkdirAll(scenariosDir, 0o755); err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal_error"})
		return
	}

	filename := filepath.Join(scenariosDir, req.ScenarioID+".jsonl")
	if err := os.WriteFile(filename, []byte(req.JSONL), 0o644); err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal_error"})
		return
	}

	writeJSON(w, http.StatusOK, map[string]string{
		"status":     "ok",
		"scenarioId": req.ScenarioID,
	})
}

func (h *Handler) scenariosList(w http.ResponseWriter, _ *http.Request) {
	entries, err := os.ReadDir(scenariosDir)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			writeJSON(w, http.StatusOK, []string{})
			return
		}
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal_error"})
		return
	}

	ids := make([]string, 0, len(entries))
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		if filepath.Ext(name) != ".jsonl" {
			continue
		}
		ids = append(ids, strings.TrimSuffix(name, ".jsonl"))
	}
	sort.Strings(ids)

	writeJSON(w, http.StatusOK, ids)
}

func writeJSON(w http.ResponseWriter, status int, payload interface{}) {
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(payload)
}

package httpapi

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strconv"
	"testing"

	"incident-replay/backend/internal/replay"
)

func setupHandler(t *testing.T) *Handler {
	t.Helper()
	setupTestScenario(t)
	runner := replay.NewRunner()
	return NewHandler(runner)
}

func setupTestScenario(t *testing.T) {
	t.Helper()
	const dir = "./data/scenarios"
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatalf("failed to create scenarios dir: %v", err)
	}
	path := filepath.Join(dir, "testscenario.jsonl")
	content := `{"ts":"2021-01-01T00:00:00Z","type":"http","method":"GET","path":"/healthz"}`
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		t.Fatalf("failed to create scenario: %v", err)
	}
	t.Cleanup(func() {
		_ = os.Remove(path)
	})
}

func TestHealthz_OKWhenDirsWritable(t *testing.T) {
	tmpDir := t.TempDir()
	origWD, err := os.Getwd()
	if err != nil {
		t.Fatalf("getwd failed: %v", err)
	}
	if err := os.Chdir(tmpDir); err != nil {
		t.Fatalf("chdir failed: %v", err)
	}
	t.Cleanup(func() {
		_ = os.Chdir(origWD)
	})

	h := setupHandler(t)

	r := httptest.NewRequest("GET", "/healthz", nil)
	w := httptest.NewRecorder()

	h.healthz(w, r)

	res := w.Result()
	defer res.Body.Close()

	if res.StatusCode != http.StatusOK {
		t.Fatalf("expected status 200, got %d", res.StatusCode)
	}

	var body map[string]string
	if err := json.NewDecoder(res.Body).Decode(&body); err != nil {
		t.Fatalf("decode body failed: %v", err)
	}
	if body["status"] != "ok" {
		t.Fatalf("expected status ok, got %s", body["status"])
	}

	// ensure dirs were created
	if _, err := os.Stat("./data/scenarios"); err != nil {
		t.Fatalf("expected scenarios dir to exist: %v", err)
	}
	if _, err := os.Stat("./data/runs"); err != nil {
		t.Fatalf("expected runs dir to exist: %v", err)
	}
}

func TestHealthz_DegradedWhenScenariosDirNotWritable(t *testing.T) {
	// create a temp dir and replace data/scenarios with a file so MkdirAll works but CreateTemp fails
	tmpDir := t.TempDir()
	origWD, err := os.Getwd()
	if err != nil {
		t.Fatalf("getwd failed: %v", err)
	}
	if err := os.Chdir(tmpDir); err != nil {
		t.Fatalf("chdir failed: %v", err)
	}
	t.Cleanup(func() {
		_ = os.Chdir(origWD)
	})

	if err := os.MkdirAll("data", 0o755); err != nil {
		t.Fatalf("mkdir data failed: %v", err)
	}

	// create a file where scenarios dir should be; MkdirAll will succeed, CreateTemp will fail
	if err := os.WriteFile("data/scenarios", []byte("not a dir"), 0o644); err != nil {
		t.Fatalf("write file failed: %v", err)
	}

	h := setupHandler(t)

	r := httptest.NewRequest("GET", "/healthz", nil)
	w := httptest.NewRecorder()

	h.healthz(w, r)

	res := w.Result()
	defer res.Body.Close()

	if res.StatusCode != http.StatusServiceUnavailable {
		t.Fatalf("expected status 503, got %d", res.StatusCode)
	}

	var body map[string]string
	if err := json.NewDecoder(res.Body).Decode(&body); err != nil {
		t.Fatalf("decode body failed: %v", err)
	}
	if body["status"] != "degraded" {
		t.Fatalf("expected status degraded, got %s", body["status"])
	}
	if body["error"] == "" {
		t.Fatalf("expected non-empty error in degraded response")
	}
}

func TestReplayStart_RPSValidation(t *testing.T) {
	h := setupHandler(t)

	// Test cases for invalid RPS
	tests := []struct {
		name     string
		rps      int
		wantErr  bool
		wantCode int
		wantBody string
	}{
		{"zero rps", 0, true, 400, `{"error":"invalid_rps"}`},
		{"negative rps", -1, true, 400, `{"error":"invalid_rps"}`},
		{"rps too large", 201, true, 400, `{"error":"invalid_rps"}`},
		{"rps equal max", 200, false, 200, ""},
		{"rps valid middle", 100, false, 200, ""},
	}

	// Save and restore env for MAX_RPS_PER_RUN
	orig := os.Getenv("MAX_RPS_PER_RUN")
	defer os.Setenv("MAX_RPS_PER_RUN", orig)

	err := os.Setenv("MAX_RPS_PER_RUN", "200")
	if err != nil {
		t.Fatalf("failed to set env: %v", err)
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			reqBody := map[string]interface{}{
				"scenarioId":    "testscenario",
				"targetBaseUrl": "http://example.com",
				"rps":           tc.rps,
				"durationSec":   1,
			}
			buf := new(bytes.Buffer)
			err := json.NewEncoder(buf).Encode(reqBody)
			if err != nil {
				t.Fatalf("encode json failed: %v", err)
			}

			r := httptest.NewRequest("POST", "/replay/start", buf)
			w := httptest.NewRecorder()

			h.replayStart(w, r)

			res := w.Result()
			defer res.Body.Close()

			if res.StatusCode != tc.wantCode {
				t.Fatalf("unexpected status code %d, want %d", res.StatusCode, tc.wantCode)
			}

			if tc.wantErr {
				var resp map[string]string
				err := json.NewDecoder(res.Body).Decode(&resp)
				if err != nil {
					t.Fatalf("failed to decode json error body: %v", err)
				}
				if resp["error"] != "invalid_rps" {
					t.Fatalf("expected error 'invalid_rps', got '%s'", resp["error"])
				}
			} else {
				// expect runId and status in response
				var resp map[string]string
				err := json.NewDecoder(res.Body).Decode(&resp)
				if err != nil {
					t.Fatalf("failed to decode json success body: %v", err)
				}
				if resp["status"] != "started" {
					t.Fatalf("expected status 'started', got '%s'", resp["status"])
				}
				if resp["runId"] == "" {
					t.Fatalf("expected non-empty runId")
				}
			}
		})
	}
}

func TestReplayStart_RPSValidation_EnvOverride(t *testing.T) {
	h := setupHandler(t)

	oldMaxRPS := os.Getenv("MAX_RPS_PER_RUN")
	defer os.Setenv("MAX_RPS_PER_RUN", oldMaxRPS)
	os.Setenv("MAX_RPS_PER_RUN", "50")

	// Reload maxRPSPerRun from environment
	maxRPS := 0
	val := os.Getenv("MAX_RPS_PER_RUN")
	if val != "" {
		v, err := strconv.Atoi(val)
		if err == nil && v > 0 {
			maxRPS = v
		} else {
			maxRPS = 200
		}
	} else {
		maxRPS = 200
	}

	if maxRPS != 50 {
		t.Fatalf("expected maxRPS to be 50, got %d", maxRPS)
	}

	// rps 51 should be invalid
	reqBody := map[string]interface{}{
		"scenarioId":    "testscenario",
		"targetBaseUrl": "http://example.com",
		"rps":           51,
		"durationSec":   1,
	}
	buf := new(bytes.Buffer)
	err := json.NewEncoder(buf).Encode(reqBody)
	if err != nil {
		t.Fatalf("encode json failed: %v", err)
	}

	r := httptest.NewRequest("POST", "/replay/start", buf)
	w := httptest.NewRecorder()

	h.replayStart(w, r)

	res := w.Result()
	defer res.Body.Close()

	if res.StatusCode != 400 {
		t.Fatalf("expected status 400, got %d", res.StatusCode)
	}

	var resp map[string]string
	err = json.NewDecoder(res.Body).Decode(&resp)
	if err != nil {
		t.Fatalf("decode json failed: %v", err)
	}

	if resp["error"] != "invalid_rps" {
		t.Fatalf("expected error invalid_rps, got %s", resp["error"])
	}
}

func TestReplayStart_ShuttingDownReturns503(t *testing.T) {
	setupTestScenario(t)
	runner := replay.NewRunner()
	runner.BeginShutdown()
	h := NewHandler(runner)

	reqBody := map[string]interface{}{
		"scenarioId":    "testscenario",
		"targetBaseUrl": "http://example.com",
		"rps":           1,
		"durationSec":   1,
	}
	buf := new(bytes.Buffer)
	if err := json.NewEncoder(buf).Encode(reqBody); err != nil {
		t.Fatalf("encode json failed: %v", err)
	}

	r := httptest.NewRequest("POST", "/replay/start", buf)
	w := httptest.NewRecorder()
	h.replayStart(w, r)

	res := w.Result()
	defer res.Body.Close()

	if res.StatusCode != 503 {
		t.Fatalf("expected status 503, got %d", res.StatusCode)
	}

	var resp map[string]string
	if err := json.NewDecoder(res.Body).Decode(&resp); err != nil {
		t.Fatalf("decode json failed: %v", err)
	}
	if resp["error"] != "shutting_down" {
		t.Fatalf("expected error shutting_down, got %s", resp["error"])
	}
}
